  float age;
  /// `mLength`: `Aim`'s (saved)
  float length;
  /// `mWidth` (saved)
  float width;
  /// `mIsTimed` (saved)
  bool timed;
  /// `mIsImpactCreated`
  bool impact_created;
  /// `mWeaponTagPoint`: the shooter's (saved from 0.250)
  int32_t weapon_tag_point;
